// Android App Bundle (.aab) for `appforshare check`: the manifest is aapt2's protobuf XML
// (base/manifest/AndroidManifest.xml), not binary XML, so it is read here with a small protobuf reader. The facts
// match what the APK inspector (src/inspect/apk.ts, generated from the website) gives the readiness rules, so the
// same rules run; the APK only rules (signature schemes, "upload an .aab") do not apply to a bundle.
import { stackOf } from '../inspect/common';
import { FACTS_VERSION, readiness, type AndroidFacts, type Readiness } from '../inspect/readiness.gen';
import { latin1, readEntry, readHead, type ZipFile } from '../inspect/zip-read';
import type { XNode } from '../inspect/security-scan';

export type PNode = { name: string; attrs: Record<string, string>; children: PNode[] };

// ---------------------------------------------------------------- protobuf

type Field = { no: number; wt: number; num: number; s: number; e: number };

function varint(b: Uint8Array, p: number): [number, number] {
  let x = 0;
  let mul = 1;
  for (let i = 0; i < 10 && p < b.length; i++) {
    const c = b[p++];
    x += (c & 0x7f) * mul;
    if (!(c & 0x80)) return [x, p];
    mul *= 128;
  }
  throw new Error('bad varint');
}

function fields(b: Uint8Array, s: number, e: number): Field[] {
  const out: Field[] = [];
  let p = s;
  while (p < e) {
    const [key, q] = varint(b, p);
    p = q;
    const no = Math.floor(key / 8);
    const wt = key & 7;
    if (wt === 0) {
      const [v, r] = varint(b, p);
      out.push({ no, wt, num: v, s: p, e: r });
      p = r;
    } else if (wt === 2) {
      const [len, r] = varint(b, p);
      out.push({ no, wt, num: len, s: r, e: r + len });
      p = r + len;
    } else if (wt === 5) {
      out.push({ no, wt, num: new DataView(b.buffer, b.byteOffset + p, 4).getUint32(0, true), s: p, e: p + 4 });
      p += 4;
    } else if (wt === 1) {
      p += 8;
    } else throw new Error('bad wire type');
  }
  if (p !== e) throw new Error('bad message');
  return out;
}

const text = (b: Uint8Array, f: Field) => new TextDecoder().decode(b.subarray(f.s, f.e));

/** aapt2 Item: a reference, a string or a primitive (bool, int). */
function itemText(b: Uint8Array, f: Field): string | null {
  for (const x of fields(b, f.s, f.e)) {
    if (x.no === 1 && x.wt === 2) {
      const ref = fields(b, x.s, x.e).find((y) => y.no === 2 && y.wt === 0);
      if (ref) return `@0x${ref.num.toString(16).padStart(8, '0')}`;
    }
    if ((x.no === 2 || x.no === 3) && x.wt === 2) {
      const v = fields(b, x.s, x.e).find((y) => y.no === 1 && y.wt === 2);
      return v ? text(b, v) : '';
    }
    if (x.no === 7 && x.wt === 2) {
      for (const p of fields(b, x.s, x.e)) {
        if (p.no === 8 && p.wt === 0) return p.num ? 'true' : 'false';
        if ((p.no === 6 || p.no === 7) && p.wt === 0) return String(p.num | 0);
      }
    }
  }
  return null;
}

function element(b: Uint8Array, s: number, e: number): PNode {
  const node: PNode = { name: '', attrs: {}, children: [] };
  for (const f of fields(b, s, e)) {
    if (f.no === 3 && f.wt === 2) node.name = text(b, f);
    else if (f.no === 4 && f.wt === 2) {
      let name = '';
      let value: string | null = null;
      let compiled: string | null = null;
      for (const a of fields(b, f.s, f.e)) {
        if (a.no === 2 && a.wt === 2) name = text(b, a);
        else if (a.no === 3 && a.wt === 2) value = text(b, a);
        else if (a.no === 6 && a.wt === 2) compiled = itemText(b, a);
      }
      // The source text ("true", "34", "@xml/network_security_config") when aapt2 kept it, else the compiled value.
      if (name) node.attrs[name] = value || compiled || '';
    } else if (f.no === 5 && f.wt === 2) {
      const el = fields(b, f.s, f.e).find((x) => x.no === 1 && x.wt === 2);
      if (el) node.children.push(element(b, el.s, el.e));
    }
  }
  return node;
}

/** aapt2 protobuf XmlNode (bundle manifests and res/xml files) to a tree; null when it is not one. */
export function parseProtoXml(b: Uint8Array): PNode | null {
  try {
    const el = fields(b, 0, b.length).find((x) => x.no === 1 && x.wt === 2);
    return el ? element(b, el.s, el.e) : null;
  } catch {
    return null;
  }
}

export function findAllP(n: PNode, name: string, out: PNode[] = []): PNode[] {
  for (const c of n.children) {
    if (c.name === name) out.push(c);
    findAllP(c, name, out);
  }
  return out;
}

/** The tree the security scan reads (same shape as the worker's aapt2 xmltree). */
export function toXNode(n: PNode, parent: XNode | null = null): XNode {
  const x: XNode = { tag: n.name, attrs: { ...n.attrs }, children: [], parent };
  x.children = n.children.map((c) => toXNode(c, x));
  return x;
}

// ---------------------------------------------------------------- facts

export type AabInspection = {
  name: string | null;
  bundleId: string | null;
  version: string | null;
  versionCode: string | null;
  permissions: string[];
  meta: Record<string, unknown>;
  readiness: Readiness;
  manifest: PNode;
  debuggable: boolean;
  testOnly: boolean;
  debugCertificate: boolean | null;
  signed: boolean;
};

function elfMinLoadAlign(h: Uint8Array): number | null {
  if (h.length < 64 || h[0] !== 0x7f || h[1] !== 0x45 || h[2] !== 0x4c || h[3] !== 0x46 || h[4] !== 2 || h[5] !== 1) return null;
  const v = new DataView(h.buffer, h.byteOffset, h.byteLength);
  const phoff = Number(v.getBigUint64(0x20, true));
  const phentsize = v.getUint16(0x36, true);
  const phnum = v.getUint16(0x38, true);
  let min: number | null = null;
  for (let i = 0; i < phnum; i++) {
    const o = phoff + i * phentsize;
    if (o + 56 > h.length) return min;
    if (v.getUint32(o, true) !== 1) continue;
    const align = Number(v.getBigUint64(o + 0x30, true));
    min = min === null ? align : Math.min(min, align);
  }
  return min;
}

export async function inspectAab(zip: ZipFile): Promise<AabInspection> {
  const m = zip.entries.get('base/manifest/AndroidManifest.xml')!;
  const manifest = parseProtoXml(await readEntry(zip, m, 8 * 1024 * 1024));
  if (!manifest || manifest.name !== 'manifest') throw new Error('The bundle manifest (base/manifest/AndroidManifest.xml) could not be read.');
  const app = findAllP(manifest, 'application')[0] ?? { name: 'application', attrs: {}, children: [] };
  const sdk = findAllP(manifest, 'uses-sdk')[0];
  const num = (n: PNode | undefined, k: string) => (n?.attrs[k] && /^\d+$/.test(n.attrs[k]) ? Number(n.attrs[k]) : null);
  const minSdk = num(sdk, 'minSdkVersion') ?? 1;
  const targetSdk = num(sdk, 'targetSdkVersion') ?? minSdk;
  const bool = (k: string) => (app.attrs[k] === undefined ? null : app.attrs[k] === 'true');
  const debuggable = bool('debuggable') === true;

  const permissions = [...new Set([...findAllP(manifest, 'uses-permission'), ...findAllP(manifest, 'uses-permission-sdk-23')].map((p) => p.attrs.name).filter((p): p is string => !!p))].map((p) =>
    p.startsWith('android.permission.') ? p.slice('android.permission.'.length) : p,
  );

  const intentHas = (a: PNode, cat: string) =>
    findAllP(a, 'intent-filter').some(
      (f) => findAllP(f, 'action').some((x) => x.attrs.name === 'android.intent.action.MAIN') && findAllP(f, 'category').some((x) => x.attrs.name === `android.intent.category.${cat}`),
    );
  const activities = [...findAllP(app, 'activity'), ...findAllP(app, 'activity-alias')];
  const launcher = activities.find((a) => intentHas(a, 'LAUNCHER'));
  const leanback = activities.some((a) => intentHas(a, 'LEANBACK_LAUNCHER'));
  const features = findAllP(manifest, 'uses-feature').map((f) => ({ name: f.attrs.name ?? null, required: f.attrs.required !== 'false' }));
  const formFactor: AndroidFacts['formFactor'] = features.some((f) => f.name === 'android.hardware.type.watch')
    ? 'wear'
    : features.some((f) => f.name === 'android.hardware.type.automotive' && f.required)
      ? 'automotive'
      : leanback && !launcher
        ? 'tv'
        : 'phone';

  // Module paths without "base/" read like an APK's (lib/<abi>/x.so, assets/...).
  const names = [...zip.entries.keys()].filter((n) => n.startsWith('base/')).map((n) => n.slice(5));
  const abis = [...new Set(names.map((n) => /^lib\/([^/]+)\/[^/]+\.so$/.exec(n)?.[1]).filter((x): x is string => !!x))];
  const libs16k: AndroidFacts['libs16k'] = [];
  for (const abi of ['arm64-v8a', 'x86_64']) {
    const libs = [...zip.entries.values()].filter((e) => e.name.startsWith(`base/lib/${abi}/`) && e.name.endsWith('.so'));
    if (!libs.length) continue;
    const misaligned: string[] = [];
    for (const e of libs.slice(0, 60)) {
      const align = elfMinLoadAlign(await readHead(zip, e, 64 * 1024).catch(() => new Uint8Array()));
      if (align !== null && align < 16384) misaligned.push(e.name.split('/').pop()!);
    }
    libs16k.push({ abi, total: libs.length, misaligned });
  }

  // A bundle is signed with jarsigner (v1) for upload to Play: META-INF/*.RSA at the root.
  const v1 = [...zip.entries.values()].find((e) => /^META-INF\/[^/]+\.(RSA|DSA|EC)$/i.test(e.name));
  const v1der = v1 ? await readEntry(zip, v1, 256 * 1024).catch(() => null) : null;
  const debugCertificate = v1der ? latin1(v1der).includes('Android Debug') : null;

  const services = findAllP(app, 'service').map((s) => s.attrs.permission);
  const facts: AndroidFacts = {
    v: FACTS_VERSION,
    stack: stackOf(names.map((n) => n.toLowerCase())),
    formFactor,
    testOnly: bool('testOnly') === true,
    cleartextTraffic: bool('usesCleartextTraffic'),
    networkSecurityConfig: !!app.attrs.networkSecurityConfig,
    libs16k,
    debugCertificate,
    signatureV2: false,
    services: [
      ...(services.includes('android.permission.BIND_ACCESSIBILITY_SERVICE') ? (['accessibility'] as const) : []),
      ...(services.includes('android.permission.BIND_VPN_SERVICE') ? (['vpn'] as const) : []),
    ],
  };
  const kernel = names.includes('assets/flutter_assets/kernel_blob.bin');
  const appLib = names.some((n) => /^lib\/[^/]+\/libapp\.so$/.test(n));
  if (kernel || appLib || names.some((n) => /^lib\/[^/]+\/libflutter\.so$/.test(n))) {
    const imp = findAllP(app, 'meta-data').find((x) => x.attrs.name === 'io.flutter.embedding.android.EnableImpeller');
    const impText = imp?.attrs.value ?? null;
    facts.flutter = { mode: kernel ? 'debug' : appLib ? (debuggable ? 'profile' : 'release') : null, engine: null, dart: null, obfuscated: null, impeller: impText === 'true' ? true : impText === 'false' ? false : null };
  }
  const meta = { minSdk: String(minSdk), targetSdk: String(targetSdk), debuggable, nativeCode: abis, facts };
  const version = manifest.attrs.versionName && !/^@/.test(manifest.attrs.versionName) ? manifest.attrs.versionName : null;
  const versionCode = manifest.attrs.versionCode ?? null;
  const r = readiness({ platform: 'ANDROID', version, versionCode, permissions, meta });
  // "APK file: upload an .aab to Play" does not apply to a bundle.
  const findings = r.findings.filter((f) => f.id !== 'android.aab');
  const label = app.attrs.label && !/^@/.test(app.attrs.label) ? app.attrs.label : null;
  return {
    name: label,
    bundleId: manifest.attrs.package ?? null,
    version,
    versionCode,
    permissions,
    meta,
    readiness: { ...r, findings, passed: findings.length === r.findings.length ? r.passed : [...r.passed, 'Upload format'] },
    manifest,
    debuggable,
    testOnly: facts.testOnly,
    debugCertificate,
    signed: !!v1der,
  };
}
